SELECT a, b, typeof(a) FROM t ORDER BY a, b;
SELECT a, b FROM t ORDER BY b DESC, a;
SELECT a FROM t ORDER BY a COLLATE NOCASE, b;
SELECT DISTINCT a FROM t ORDER BY 1;
SELECT a, count(*) FROM t GROUP BY a ORDER BY 2 DESC, 1;
